  const declared=String(item?.category||'').toLowerCase(); const key=String(item?.key||'');
  if(declared==='status'||declared==='event'||/\.Status\.|\.Event\./.test(key))return 'status';
  if(declared==='setting'||/\.Setting\./.test(key))return 'setting';
  return 'value';
};
